'use client'

import {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type HTMLAttributes,
  type MouseEvent,
  type PointerEvent,
} from 'react'
import { animate, motion, useMotionValue, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import { playHoverSound, playClickSound } from '@/lib/sound'

const TRACK_WIDTH = 44
const THUMB_SIZE = 20
const THUMB_INSET = 2
const THUMB_TRAVEL = TRACK_WIDTH - THUMB_SIZE - THUMB_INSET * 2

export interface SwitchProps extends Omit<HTMLAttributes<HTMLButtonElement>, 'onChange'> {
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
  label?: string
  labelSide?: 'left' | 'right'
  name?: string
  value?: string
  form?: string
  disabled?: boolean
  readOnly?: boolean
  required?: boolean
  trackClassName?: string
  thumbClassName?: string
  labelClassName?: string
  'aria-invalid'?: boolean
  'aria-describedby'?: string
}

export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(
  (
    {
      checked: checkedProp,
      defaultChecked = false,
      onCheckedChange,
      label,
      labelSide = 'right',
      disabled = false,
      readOnly = false,
      name,
      value: formValue = 'on',
      form,
      required,
      className,
      trackClassName,
      thumbClassName,
      labelClassName,
      id: idProp,
      onClick,
      onMouseEnter,
      onPointerDown,
      onPointerUp,
      onPointerCancel,
      onPointerLeave,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-invalid': ariaInvalid,
      'aria-describedby': ariaDescribedBy,
      ...buttonProps
    },
    forwardedRef,
  ) => {
    const reactId = useId()
    const id = idProp ?? reactId
    const labelId = label ? `${id}-label` : undefined
    const isControlled = checkedProp !== undefined
    const [internalChecked, setInternalChecked] = useState(defaultChecked)
    const checked = isControlled ? checkedProp : internalChecked
    const reduceMotion = useReducedMotion()
    const buttonRef = useRef<HTMLButtonElement | null>(null)
    const nativeInputRef = useRef<HTMLInputElement | null>(null)
    const thumbScaleX = useMotionValue(1)
    const isInteractive = !disabled && !readOnly
    const [isRtl, setIsRtl] = useState(false)

    useEffect(() => {
      const node = buttonRef.current
      if (!node) return
      setIsRtl(getComputedStyle(node).direction === 'rtl')
    }, [])

    const setRefs = useCallback(
      (node: HTMLButtonElement | null) => {
        buttonRef.current = node
        if (typeof forwardedRef === 'function') {
          forwardedRef(node)
        } else if (forwardedRef) {
          forwardedRef.current = node
        }
      },
      [forwardedRef],
    )

    useEffect(() => {
      if (isControlled) return
      const owningForm = nativeInputRef.current?.form
      if (!owningForm) return

      const reset = () => setInternalChecked(defaultChecked)
      owningForm.addEventListener('reset', reset)
      return () => owningForm.removeEventListener('reset', reset)
    }, [defaultChecked, isControlled])

    const settleThumb = useCallback(() => {
      if (reduceMotion) return
      animate(thumbScaleX, 1, springs.settle)
    }, [reduceMotion, thumbScaleX])

    const handleClick = useCallback(
      (event: MouseEvent<HTMLButtonElement>) => {
        onClick?.(event)
        if (event.defaultPrevented || !isInteractive) {
          if (!disabled) event.preventDefault()
          return
        }

        const nextChecked = !checked
        if (!isControlled) setInternalChecked(nextChecked)
        playClickSound()
        onCheckedChange?.(nextChecked)
      },
      [onClick, isInteractive, disabled, checked, isControlled, onCheckedChange],
    )

    const handleMouseEnter = useCallback(
      (event: MouseEvent<HTMLButtonElement>) => {
        onMouseEnter?.(event)
        if (!event.defaultPrevented && isInteractive) playHoverSound()
      },
      [onMouseEnter, isInteractive],
    )

    const handlePointerDown = useCallback(
      (event: PointerEvent<HTMLButtonElement>) => {
        onPointerDown?.(event)
        if (event.defaultPrevented || reduceMotion || !isInteractive) return
        animate(thumbScaleX, 1.15, springs.press)
      },
      [onPointerDown, reduceMotion, isInteractive, thumbScaleX],
    )

    const handlePointerUp = useCallback(
      (event: PointerEvent<HTMLButtonElement>) => {
        onPointerUp?.(event)
        settleThumb()
      },
      [onPointerUp, settleThumb],
    )

    const handlePointerCancel = useCallback(
      (event: PointerEvent<HTMLButtonElement>) => {
        onPointerCancel?.(event)
        settleThumb()
      },
      [onPointerCancel, settleThumb],
    )

    const handlePointerLeave = useCallback(
      (event: PointerEvent<HTMLButtonElement>) => {
        onPointerLeave?.(event)
        settleThumb()
      },
      [onPointerLeave, settleThumb],
    )

    return (
      <div
        className={cn(
          'flex items-center gap-3',
          labelSide === 'left' && 'flex-row-reverse',
          className,
        )}
        data-state={checked ? 'checked' : 'unchecked'}
        data-disabled={disabled ? '' : undefined}
        data-readonly={readOnly ? '' : undefined}
      >
        <input
          ref={nativeInputRef}
          type="checkbox"
          name={name}
          value={formValue}
          form={form}
          checked={checked}
          disabled={disabled}
          required={required}
          readOnly
          aria-hidden="true"
          className="sr-only"
          tabIndex={-1}
        />
        <button
          ref={setRefs}
          id={id}
          type="button"
          {...buttonProps}
          role="switch"
          aria-checked={checked}
          aria-label={label ? undefined : ariaLabel}
          aria-labelledby={ariaLabelledBy ?? labelId}
          aria-readonly={readOnly || undefined}
          aria-required={required || undefined}
          aria-invalid={ariaInvalid}
          aria-describedby={ariaDescribedBy}
          disabled={disabled}
          data-state={checked ? 'checked' : 'unchecked'}
          data-disabled={disabled ? '' : undefined}
          data-readonly={readOnly ? '' : undefined}
          onClick={handleClick}
          onMouseEnter={handleMouseEnter}
          onPointerDown={handlePointerDown}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerCancel}
          onPointerLeave={handlePointerLeave}
          className={cn(
            'relative inline-block h-6 w-11 shrink-0 squircle transition-colors duration-(--motion-dur-fast) ease-(--motion-ease-out)',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)',
            'disabled:cursor-not-allowed disabled:opacity-50',
            readOnly && 'cursor-default opacity-75',
            checked ? 'bg-(--color-fg)' : 'bg-(--color-border)',
            ariaInvalid && 'ring-2 ring-(--color-error) ring-offset-2 ring-offset-(--color-bg)',
            'motion-reduce:transition-none',
            trackClassName,
          )}
        >
          <motion.span
            animate={{ x: checked ? (isRtl ? -THUMB_TRAVEL : THUMB_TRAVEL) : 0 }}
            transition={reduceMotion ? { duration: 0 } : springs.settle}
            className={cn(
              'pointer-events-none absolute inset-y-0.5 start-0.5 block size-5 squircle bg-(--color-bg) shadow-sm',
              thumbClassName,
            )}
            style={{ scaleX: thumbScaleX }}
          />
        </button>
        {label && (
          <label
            id={labelId}
            htmlFor={id}
            className={cn(
              'flex min-h-6 items-center text-sm text-(--color-fg) select-none',
              disabled
                ? 'cursor-not-allowed opacity-50'
                : readOnly
                  ? 'cursor-default'
                  : 'cursor-pointer',
              labelClassName,
            )}
          >
            {label}
          </label>
        )}
      </div>
    )
  },
)
Switch.displayName = 'Switch'

export function SwitchPreview() {
  const [checked, setChecked] = useState(false)
  return (
    <div className="flex h-full w-full items-center justify-center p-6">
      <div className="space-y-3">
        <Switch checked={checked} onCheckedChange={setChecked} label="Notifications" />
        <Switch defaultChecked label="Dark mode" />
        <Switch checked disabled label="Disabled" />
      </div>
    </div>
  )
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playTileNote(frequency = 440, volume = 0.08) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime
    const dur = 1.1

    const osc = ctx.createOscillator()
    const shimmer = ctx.createOscillator()
    const shimmerGain = ctx.createGain()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(frequency, now)
    shimmer.type = 'sine'
    shimmer.frequency.setValueAtTime(frequency * 2, now)

    shimmerGain.gain.setValueAtTime(0.22, now)
    shimmerGain.gain.exponentialRampToValueAtTime(0.0001, now + dur * 0.5)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.015)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur)

    shimmer.connect(shimmerGain)
    shimmerGain.connect(gain)
    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + dur)
    shimmer.start(now)
    shimmer.stop(now + dur)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
